syntax:
std::map<KeyType, ValueType> myMap;
// Accessing or inserting: myMap[key] = value;  // If 'key' doesn't exist, a new element is inserted with 'key' and a value-initialized ValueType (e.g., int defaults to 0).
// Practical usage note: Prefer myMap.at(key) for bounds-checked access (throws if key not found) or myMap.find(key) != myMap.end() to check existence before modification, ensuring idiomatic and safe code.

code_example:
#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, int> wordCount;  // A map to count word occurrences

    // Simulating word frequency: If key doesn't exist, it's inserted with 0
    std::string word = "example";
    wordCount[word]++;  // Accesses value for 'example' and increments; inserts with 0 if not present

    // Output the result
    std::cout << "Count of '" << word << "': " << wordCount[word] << std::endl;  // Outputs: Count of 'example': 1

    return 0;
}
